from griffe import Extension, load_extensions, load

class CheckedExtension(Extension):
    """Extension that appends ' [checked]' to all function docstrings."""

    def on_function_instance(self, func):
        """Run when a Function has been created."""
        if func.docstring:
            func.docstring.value += " [checked]"
        else:
            func.docstring = " [checked]"

# Aggregate extension using load_extensions
extensions = load_extensions(CheckedExtension)

# Load the package with the extension enabled
module = load("mypkg", extensions=extensions)

# Print results to verify
for name, obj in module.members.items():
    if hasattr(obj, 'docstring') and obj.docstring:
        print(f"{name}: {obj.docstring}")

